await page.evaluate('async () => {const wait=()=>new Promise(r=>setTimeout(r,40)); const report=[];for(const label of [\'File\',\'Edit\',\'View\',\'Insert\',\'Format\',\'Styles\',\'Sheet\',\'Data\',\'Tools\',\'Window\',\'Help\']){[...document.querySelectorAll(\'button\')].find(b=>b.textContent.trim()===label).click();await wait();const menu=document.querySelector(\'[role=menu]\');if(!menu)throw Error(label);const shortcuts=[...menu.querySelectorAll(\'[aria-keyshortcuts]\')].map(b=>({caption:b.textContent.trim(),shortcut:b.getAttribute(\'aria-keyshortcuts\'),disabled:b.disabled}));report.push({menu:label,shortcuts});menu.dispatchEvent(new KeyboardEvent(\'keydown\',{key:\'Escape\',bubbles:true}));await wait();}const dialogs=[];for(const label of [\'Open…\',\'Save As…\',\'Export…\']){[...document.querySelectorAll(\'button\')].find(b=>b.textContent.trim()===\'File\').click();await wait();const item=[...document.querySelectorAll(\'[role=menuitem]\')].find(b=>b.textContent.startsWith(label));item.click();await wait();const dialog=document.querySelector(\'[role=dialog]\');if(!dialog)throw Error(\'No dialog \'+label);dialogs.push({command:label,dialog:dialog.getAttribute(\'aria-label\')});dialog.dispatchEvent(new KeyboardEvent(\'keydown\',{key:\'Escape\',bubbles:true}));await wait();}return {url:location.href,menus:report,dialogs,menuCrashes:0};}');
